import { readFileSync } from 'node:fs';

import { expect, sample, test, uniqueName } from '../../fixtures';

type DocumentRow = { id: string; kind: string; status: string };

test('rejecting an extraction requires a note and returns the vendor to the member', { tag: '@REV-06' }, async ({ apiAs }) => {
  // Arrange: a vendor in review with three pending extractions
  const member = await apiAs('member');
  const reviewer = await apiAs('reviewer');

  const created = await member.post('/api/vendors', {
    data: { name: uniqueName('REV-06 Vendor'), category: 'logistics', contact_email: 'ops@acme.example' },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();

  for (const [kind, file] of [
    ['w9', 'w9.txt'],
    ['insurance_certificate', 'insurance_certificate.txt'],
    ['contract', 'contract.txt'],
  ] as const) {
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind,
        file: { name: file, mimeType: 'text/plain', buffer: readFileSync(sample(file)) },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  const listDocuments = async (): Promise<DocumentRow[]> => {
    const res = await member.get(`/api/vendors/${vendor.id}/documents`);
    expect(res.status(), await res.text()).toBe(200);
    return (await res.json()) as DocumentRow[];
  };

  // Extraction runs in the background; wait until every document has been extracted.
  await expect
    .poll(async () => (await listDocuments()).every((d) => d.status === 'extracted'), { timeout: 60_000 })
    .toBe(true);

  const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);
  expect((await submitted.json()).status).toBe('in_review');

  const w9Document = (await listDocuments()).find((d) => d.kind === 'w9');
  expect(w9Document, 'w9 document exists').toBeDefined();
  const extractionRes = await member.get(`/api/documents/${w9Document!.id}/extraction`);
  expect(extractionRes.status(), await extractionRes.text()).toBe(200);
  const extraction = await extractionRes.json();
  expect(extraction.status).toBe('pending_review');

  // Act + Assert: reject without a note is refused
  const withoutNote = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: 'reject' },
  });
  expect(withoutNote.status(), await withoutNote.text()).toBe(422);

  // Act + Assert: reject with a note succeeds
  const withNote = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: 'reject', note: 'Tax ID does not match' },
  });
  expect(withNote.status(), await withNote.text()).toBe(200);
  expect((await withNote.json()).status).toBe('rejected');

  // The vendor returns to the member as rejected
  await expect
    .poll(async () => {
      const res = await member.get(`/api/vendors/${vendor.id}`);
      return (await res.json()).status;
    }, { timeout: 30_000 })
    .toBe('rejected');

  // And the audit trail records the rejection
  await expect
    .poll(async () => {
      const res = await member.get(`/api/vendors/${vendor.id}/audit`);
      const trail = (await res.json()) as { items: { action: string }[] };
      return trail.items.map((event) => event.action);
    }, { timeout: 30_000 })
    .toContain('extraction.rejected');
});
